20	    const control = event.target.closest?.('[data-pick-folder], a[data-pop-out], a[target="_blank"]');
21	    if (!control || event.defaultPrevented || event.button !== 0) return;
22	    event.preventDefault();
23	    event.stopPropagation();
24	    run(control).catch(error => console.error('Prelude desktop:', error));
25	  }, true);
